async function fetchData() {
    try {
        const res = await fetch('/api/data');
        if (!res.ok) throw new Error(`HTTP ${res.status}`);
        return await res.json();
    } catch (error) {
        console.error('Fetch failed:', error);
        throw error; // Re-throw for caller to handle
    }
}

